PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, display_name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE RESTRICT, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name TEXT NOT NULL, scenario TEXT NOT NULL, seed INTEGER NOT NULL, algorithm TEXT NOT NULL CHECK(algorithm IN ('centralized','negotiation')), tick INTEGER NOT NULL DEFAULT 0 CHECK(tick>=0), status TEXT NOT NULL CHECK(status IN ('paused','running')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS neighborhoods (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, name TEXT NOT NULL, x REAL NOT NULL, y REAL NOT NULL);
CREATE TABLE IF NOT EXISTS nodes (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, neighborhood_id TEXT REFERENCES neighborhoods(id) ON DELETE SET NULL, label TEXT NOT NULL, kind TEXT NOT NULL, x REAL NOT NULL, y REAL NOT NULL);
CREATE TABLE IF NOT EXISTS edges (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, source TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE, target TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE, cost INTEGER NOT NULL CHECK(cost>0), accessibility TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('open','closed')), safety TEXT NOT NULL CHECK(safety IN ('safe','unsafe','uncertain')), capacity INTEGER NOT NULL DEFAULT 1 CHECK(capacity>0));
CREATE TABLE IF NOT EXISTS incidents (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, node_id TEXT NOT NULL REFERENCES nodes(id), neighborhood_id TEXT REFERENCES neighborhoods(id), title TEXT NOT NULL, category TEXT NOT NULL, severity INTEGER NOT NULL CHECK(severity BETWEEN 1 AND 5), urgency INTEGER NOT NULL CHECK(urgency BETWEEN 1 AND 5), people INTEGER NOT NULL CHECK(people>0), status TEXT NOT NULL, confidence REAL NOT NULL CHECK(confidence BETWEEN 0 AND 1), created_tick INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS resources (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, label TEXT NOT NULL, node_id TEXT NOT NULL REFERENCES nodes(id), capacity INTEGER NOT NULL CHECK(capacity>0), capabilities TEXT NOT NULL, status TEXT NOT NULL, assignment_id TEXT);
CREATE TABLE IF NOT EXISTS shelters (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, node_id TEXT NOT NULL REFERENCES nodes(id), name TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>0), occupancy INTEGER NOT NULL DEFAULT 0 CHECK(occupancy>=0 AND occupancy<=capacity), accessible INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, idempotency_key TEXT NOT NULL, tick INTEGER NOT NULL, sequence INTEGER NOT NULL, kind TEXT NOT NULL, payload TEXT NOT NULL, processed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(session_id,idempotency_key));
CREATE TABLE IF NOT EXISTS assignments (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, incident_id TEXT NOT NULL REFERENCES incidents(id), resource_id TEXT NOT NULL REFERENCES resources(id), shelter_id TEXT REFERENCES shelters(id), status TEXT NOT NULL, route TEXT NOT NULL, travel_cost INTEGER NOT NULL, reason TEXT NOT NULL, created_tick INTEGER NOT NULL, ended_tick INTEGER);
CREATE TABLE IF NOT EXISTS bids (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, incident_id TEXT NOT NULL REFERENCES incidents(id), resource_id TEXT NOT NULL REFERENCES resources(id), score REAL NOT NULL, status TEXT NOT NULL, reason TEXT NOT NULL, tick INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audits (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, tick INTEGER NOT NULL, passed INTEGER NOT NULL, findings TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS snapshots (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, tick INTEGER NOT NULL, state TEXT NOT NULL, UNIQUE(session_id,tick));
CREATE INDEX IF NOT EXISTS idx_incidents_session_status ON incidents(session_id,status);
CREATE INDEX IF NOT EXISTS idx_events_tick ON events(session_id,tick,sequence);
CREATE INDEX IF NOT EXISTS idx_assignments_session_status ON assignments(session_id,status);
CREATE UNIQUE INDEX IF NOT EXISTS idx_one_active_incident ON assignments(session_id,incident_id) WHERE status='active';
CREATE UNIQUE INDEX IF NOT EXISTS idx_one_active_resource ON assignments(session_id,resource_id) WHERE status='active';
CREATE INDEX IF NOT EXISTS idx_bids_session_tick ON bids(session_id,tick);
